syntax = "proto3";

package flipt.auth;

import "google/protobuf/empty.proto";
import "google/protobuf/struct.proto";
import "google/protobuf/timestamp.proto";
import "google/api/annotations.proto";
import "gnostic/openapi/v3/annotations.proto";

option go_package = "go.flipt.io/flipt/rpc/flipt/auth";

option (gnostic.openapi.v3.document) = {
  components: {
    security_schemes: {
      additional_properties: [
        {
          name: "bearerAuth";
          value: {
            security_scheme: {
              type: "http";
              scheme: "bearer";
            }
          }
        },
        {
          name: "jwtAuth";
          value: {
            security_scheme: {
              type: "http";
              scheme: "JWT";
            }
          }
        }
      ]
    }
  }
  servers: {
    url: "http://localhost:8080";
  }
  security: {
    additional_properties: [
      {
        name: "bearerAuth",
        value: {
          value: []
        }
      }
    ]
  }
};


enum Method {
  METHOD_NONE = 0;
  METHOD_TOKEN = 1;
  METHOD_OIDC = 2;
  METHOD_KUBERNETES = 3;
  METHOD_GITHUB = 4;
  METHOD_JWT = 5;
  METHOD_CLOUD = 6;
}

message MethodInfo {
  Method method = 1;
  bool enabled = 2;
  bool session_compatible = 3;
  google.protobuf.Struct metadata = 4;
}

message ListAuthenticationMethodsResponse {
  repeated MethodInfo methods = 1;
}

service PublicAuthenticationService {
  rpc ListAuthenticationMethods(google.protobuf.Empty) returns (ListAuthenticationMethodsResponse) {}
}

message Authentication {
  string id = 1;
  Method method = 2;
  google.protobuf.Timestamp expires_at = 3;
  google.protobuf.Timestamp created_at = 4;
  google.protobuf.Timestamp updated_at = 5;
  map<string, string> metadata = 6;
}

message GetAuthenticationRequest {
  string id = 1;
}

message ListAuthenticationsRequest {
  Method method = 1;
  int32 limit = 2;
  string page_token = 3;
}

message ListAuthenticationsResponse {
  repeated Authentication authentications = 1;
  string next_page_token = 2;
}

message DeleteAuthenticationRequest {
  string id = 1;
}

message ExpireAuthenticationSelfRequest {
  optional google.protobuf.Timestamp expires_at = 1;
}

service AuthenticationService {
  rpc GetAuthenticationSelf(google.protobuf.Empty) returns (Authentication) {
    option (google.api.http) = {
      get: "/auth/v1/self"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "getAuthSelf"
    };
  }
  rpc GetAuthentication(GetAuthenticationRequest) returns (Authentication) {
    option (google.api.http) = {
      get: "/auth/v1/tokens/{id}"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "getAuthToken"
    };
  }
  rpc ListAuthentications(ListAuthenticationsRequest) returns (ListAuthenticationsResponse) {
    option (google.api.http) = {
      get: "/auth/v1/tokens"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "listAuthTokens"
    };
  }
  rpc DeleteAuthentication(DeleteAuthenticationRequest) returns (google.protobuf.Empty) {
    option (google.api.http) = {
      delete: "/auth/v1/tokens/{id}"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "deleteAuthToken"
    };
  }
  rpc ExpireAuthenticationSelf(ExpireAuthenticationSelfRequest) returns (google.protobuf.Empty) {
    option (google.api.http) = {
      put: "/auth/v1/self/expire"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "expireAuthSelf"
    };
  }
}

message CreateTokenRequest {
  string name = 1;
  string description = 2;
  google.protobuf.Timestamp expires_at = 3;
  string namespace_key = 4;
  map<string, string> metadata = 7;
}

message CreateTokenResponse {
  string client_token = 1;
  Authentication authentication = 2;
}

service AuthenticationMethodTokenService {
  rpc CreateToken(CreateTokenRequest) returns (CreateTokenResponse) {
    option (google.api.http) = {
      post: "/auth/v1/method/token"
      body: "*"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "createMethodToken"
    };
  }
}

message AuthorizeURLRequest {
  string provider = 1;
  string state = 2;
}

message AuthorizeURLResponse {
  string authorize_url = 1;
}

message CallbackRequest {
  string provider = 1;
  string code = 2;
  string state = 3;
}

message CallbackResponse {
  string client_token = 1;
  Authentication authentication = 2;
}

service AuthenticationMethodOIDCService {
  rpc AuthorizeURL(AuthorizeURLRequest) returns (AuthorizeURLResponse) {
    option (google.api.http) = {
      get: "/auth/v1/method/oidc/{provider}/authorize"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "oidcAuthorizeURL"
    };
  }
  rpc Callback(CallbackRequest) returns (CallbackResponse) {
    option (google.api.http) = {
      get: "/auth/v1/method/oidc/{provider}/callback"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "oidcCallback"
    };
  }
}

message VerifyServiceAccountRequest {
  string service_account_token = 1;
}

message VerifyServiceAccountResponse {
  string client_token = 1;
  Authentication authentication = 2;
}

service AuthenticationMethodKubernetesService {
  rpc VerifyServiceAccount(VerifyServiceAccountRequest) returns (VerifyServiceAccountResponse) {
    option (google.api.http) = {
      post: "/auth/v1/method/kubernetes/serviceaccount"
      body: "*"
    };
    option (gnostic.openapi.v3.operation) = {
      operation_id: "kubernetesVerifyServiceAccount"
    };
  }
}

service AuthenticationMethodGithubService {
  rpc AuthorizeURL(AuthorizeURLRequest) returns (AuthorizeURLResponse) {}
  rpc Callback(CallbackRequest) returns (CallbackResponse) {}
}
package rego

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/open-policy-agent/opa/rego"
	"github.com/open-policy-agent/opa/storage"
	"github.com/open-policy-agent/opa/storage/inmem"
	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/server/authz"
	"go.flipt.io/flipt/internal/server/authz/engine/rego/source"
	"go.flipt.io/flipt/internal/server/authz/engine/rego/source/cloud"
	"go.flipt.io/flipt/internal/server/authz/engine/rego/source/filesystem"
	"go.uber.org/zap"
)

var (
	_                         authz.Verifier = (*Engine)(nil)
	defaultPolicyPollDuration                = 5 * time.Minute
)

type CachedSource[T any] interface {
	Get(_ context.Context, hash source.Hash) (T, source.Hash, error)
}

type PolicySource CachedSource[[]byte]

type DataSource CachedSource[map[string]any]

type Engine struct {
	logger *zap.Logger

	mu    sync.RWMutex
	query rego.PreparedEvalQuery
	store storage.Store

	policySource PolicySource
	policyHash   source.Hash

	dataSource DataSource
	dataHash   source.Hash

	policySourcePollDuration time.Duration
	dataSourcePollDuration   time.Duration
}

func withPolicySource(source PolicySource) containers.Option[Engine] {
	return func(e *Engine) {
		e.policySource = source
	}
}

func withDataSource(source DataSource, pollDuration time.Duration) containers.Option[Engine] {
	return func(e *Engine) {
		e.dataSource = source
		e.dataSourcePollDuration = pollDuration
	}
}

func withPolicySourcePollDuration(dur time.Duration) containers.Option[Engine] {
	return func(e *Engine) {
		e.policySourcePollDuration = dur
	}
}

// NewEngine creates a new local authorization engine
func NewEngine(ctx context.Context, logger *zap.Logger, cfg *config.Config) (*Engine, error) {
	var (
		opts       []containers.Option[Engine]
		authConfig = cfg.Authorization
	)

	switch authConfig.Backend {
	case config.AuthorizationBackendLocal:
		opts = []containers.Option[Engine]{
			withPolicySource(filesystem.PolicySourceFromPath(authConfig.Local.Policy.Path)),
		}

		if authConfig.Local.Policy.PollInterval > 0 {
			opts = append(opts, withPolicySourcePollDuration(authConfig.Local.Policy.PollInterval))
		}

		if authConfig.Local.Data != nil {
			opts = append(opts, withDataSource(
				filesystem.DataSourceFromPath(authConfig.Local.Data.Path),
				authConfig.Local.Data.PollInterval,
			))
		}

	case config.AuthorizationBackendCloud:
		opts = []containers.Option[Engine]{
			withPolicySource(cloud.PolicySourceFromCloud(cfg.Cloud.Host, cfg.Cloud.Authentication.ApiKey)),
			withDataSource(cloud.DataSourceFromCloud(cfg.Cloud.Host, cfg.Cloud.Authentication.ApiKey), authConfig.Cloud.PollInterval),
		}

	default:
		return nil, fmt.Errorf("unsupported authorization backend: %s", authConfig.Backend)
	}

	return newEngine(ctx, logger, opts...)
}

// newEngine creates a new engine with the provided options, visible for testing
func newEngine(ctx context.Context, logger *zap.Logger, opts ...containers.Option[Engine]) (*Engine, error) {
	engine := &Engine{
		logger:                   logger,
		store:                    inmem.New(),
		policySourcePollDuration: defaultPolicyPollDuration,
	}

	containers.ApplyAll(engine, opts...)

	// update data store with initial data if source is configured
	if err := engine.updateData(ctx, storage.AddOp); err != nil {
		return nil, err
	}

	// fetch policy and then compile and set query engine
	if err := engine.updatePolicy(ctx); err != nil {
		return nil, err
	}

	// begin polling for updates for policy
	go poll(ctx, engine.policySourcePollDuration, func() {
		if err := engine.updatePolicy(ctx); err != nil {
			engine.logger.Error("updating policy", zap.Error(err))
		}
	})

	// being polling for updates to data if source configured
	if engine.dataSource != nil {
		go poll(ctx, engine.policySourcePollDuration, func() {
			if err := engine.updateData(ctx, storage.ReplaceOp); err != nil {
				engine.logger.Error("updating data", zap.Error(err))
			}
		})
	}

	return engine, nil
}

func (e *Engine) IsAllowed(ctx context.Context, input map[string]interface{}) (bool, error) {
	e.mu.RLock()
	defer e.mu.RUnlock()

	e.logger.Debug("evaluating policy", zap.Any("input", input))

	results, err := e.query.Eval(ctx, rego.EvalInput(input))
	if err != nil {
		return false, err
	}

	if len(results) == 0 {
		return false, nil
	}

	return results[0].Expressions[0].Value.(bool), nil
}

func (e *Engine) Shutdown(_ context.Context) error {
	return nil
}

func poll(ctx context.Context, d time.Duration, fn func()) {
	ticker := time.NewTicker(d)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			fn()
		}
	}
}

func (e *Engine) updatePolicy(ctx context.Context) error {
	e.mu.Lock()
	defer e.mu.Unlock()

	policy, hash, err := e.policySource.Get(ctx, e.policyHash)
	if err != nil {
		if errors.Is(err, source.ErrNotModified) {
			return nil
		}

		return fmt.Errorf("getting policy definition: %w", err)
	}

	e.policyHash = hash

	r := rego.New(
		rego.Query("data.flipt.authz.v1.allow"),
		rego.Module("policy.rego", string(policy)),
		rego.Store(e.store),
	)

	e.query, err = r.PrepareForEval(ctx)
	if err != nil {
		return fmt.Errorf("preparing policy: %w", err)
	}

	return nil
}

func (e *Engine) updateData(ctx context.Context, op storage.PatchOp) (err error) {
	if e.dataSource == nil {
		return nil
	}

	data, hash, err := e.dataSource.Get(ctx, e.dataHash)
	if err != nil {
		if errors.Is(err, source.ErrNotModified) {
			return nil
		}

		return fmt.Errorf("getting data for policy evaluation: %w", err)
	}

	e.dataHash = hash

	txn, err := e.store.NewTransaction(ctx, storage.WriteParams)
	if err != nil {
		return err
	}

	if err := e.store.Write(ctx, txn, op, storage.Path{}, data); err != nil {
		return err
	}

	return e.store.Commit(ctx, txn)
}
package bundle

import (
	"context"
	"os"
	"strings"

	"github.com/open-policy-agent/contrib/logging/plugins/ozap"
	"github.com/open-policy-agent/opa/sdk"
	"github.com/open-policy-agent/opa/storage/inmem"
	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/server/authz"
	"go.uber.org/zap"
)

var _ authz.Verifier = (*Engine)(nil)

type cleanupFunc func()

type Engine struct {
	opa          *sdk.OPA
	logger       *zap.Logger
	cleanupFuncs []cleanupFunc
}

func NewEngine(ctx context.Context, logger *zap.Logger, cfg *config.Config) (*Engine, error) {
	var (
		authConfig   = cfg.Authorization
		opaConfig    string
		cleanupFuncs []cleanupFunc
	)

	switch authConfig.Backend {
	case config.AuthorizationBackendObject:
		opaConfig = authConfig.Object.String()

		switch authConfig.Object.Type { //nolint
		case config.S3ObjectAuthorizationBackendType:
			// set AWS_REGION env var if not set and region is specified
			// this is a nicety as the OPA env credentials provider requires this env var
			// to be set, but we don't want the user to have to supply it twice if they already have it in the config
			if authConfig.Object.S3.Region != "" && os.Getenv("AWS_REGION") == "" {
				os.Setenv("AWS_REGION", authConfig.Object.S3.Region)
				cleanupFuncs = append(cleanupFuncs, func() {
					os.Unsetenv("AWS_REGION")
				})
			}
		}
	case config.AuthorizationBackendBundle:
		opaConfig = authConfig.Bundle.String()
	}

	level := zap.NewAtomicLevelAt(logger.Level())

	opa, err := sdk.New(ctx, sdk.Options{
		Config: strings.NewReader(opaConfig),
		Store:  inmem.New(),
		Logger: ozap.Wrap(logger, &level),
	})
	if err != nil {
		return nil, err
	}

	return &Engine{
		logger:       logger,
		opa:          opa,
		cleanupFuncs: cleanupFuncs,
	}, nil
}

func (e *Engine) IsAllowed(ctx context.Context, input map[string]interface{}) (bool, error) {
	e.logger.Debug("evaluating policy", zap.Any("input", input))
	dec, err := e.opa.Decision(ctx, sdk.DecisionOptions{
		Path:  "flipt/authz/v1/allow",
		Input: input,
	})

	if err != nil {
		return false, err
	}

	allow, _ := dec.Result.(bool)
	return allow, nil
}

func (e *Engine) Shutdown(ctx context.Context) error {
	e.opa.Stop(ctx)
	for _, cleanup := range e.cleanupFuncs {
		cleanup()
	}
	return nil
}

package rego

import (
	"context"
	"encoding/json"
	"os"
	"testing"
	"time"

	"github.com/stretchr/testify/require"
	"go.flipt.io/flipt/internal/server/authz/engine/rego/source"
	"go.uber.org/zap/zaptest"
)

func TestEngine_NewEngine(t *testing.T) {
	ctx := context.Background()

	policy, err := os.ReadFile("../testdata/rbac.rego")
	require.NoError(t, err)

	data, err := os.ReadFile("../testdata/rbac.json")
	require.NoError(t, err)

	engine, err := newEngine(ctx, zaptest.NewLogger(t), withPolicySource(policySource(string(policy))), withDataSource(dataSource(string(data)), 5*time.Second))
	require.NoError(t, err)
	require.NotNil(t, engine)
}

func TestEngine_IsAllowed(t *testing.T) {
	var tests = []struct {
		name     string
		input    string
		expected bool
	}{
		{
			name: "admin is allowed to create",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "admin"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "admin is allowed to read",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "admin"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is allowed to create flags",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is allowed to read",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: true,
		},
		{
			name: "editor is not allowed to create namespaces",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "editor"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "namespace"
                }
            }`,
			expected: false,
		},
		{
			name: "viewer is allowed to read",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "segment"
                }
            }`,
			expected: true,
		},
		{
			name: "viewer is not allowed to create",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "viewer"
                    }
                },
                "request": {
                    "action": "create",
                    "resource": "flag"
                }
            }`,
			expected: false,
		},
		{
			name: "namespaced_viewer is allowed to read in namespace",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag",
                    "namespace": "foo"
                }
            }`,
			expected: true,
		},
		{
			name: "namespaced_viewer is not allowed to read in unexpected namespace",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag",
                    "namespace": "bar"
                }
            }`,
			expected: false,
		},
		{
			name: "namespaced_viewer is not allowed to read in without namespace scope",
			input: `{
                "authentication": {
                    "method": "METHOD_JWT",
                    "metadata": {
                        "io.flipt.auth.role": "namespaced_viewer"
                    }
                },
                "request": {
                    "action": "read",
                    "resource": "flag"
                }
            }`,
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			policy, err := os.ReadFile("../testdata/rbac.rego")
			require.NoError(t, err)

			data, err := os.ReadFile("../testdata/rbac.json")
			require.NoError(t, err)

			ctx := context.Background()
			engine, err := newEngine(ctx, zaptest.NewLogger(t), withPolicySource(policySource(string(policy))), withDataSource(dataSource(string(data)), 5*time.Second))
			require.NoError(t, err)

			var input map[string]interface{}

			err = json.Unmarshal([]byte(tt.input), &input)
			require.NoError(t, err)

			allowed, err := engine.IsAllowed(ctx, input)
			require.NoError(t, err)
			require.Equal(t, tt.expected, allowed)
		})
	}
}

type policySource string

func (p policySource) Get(context.Context, source.Hash) ([]byte, source.Hash, error) {
	return []byte(p), nil, nil
}

type dataSource string

func (d dataSource) Get(context.Context, source.Hash) (data map[string]any, _ source.Hash, _ error) {
	return data, nil, json.Unmarshal([]byte(d), &data)
}
